// internal/distributed/proxy/httpserver/timeout_middleware.go lines 183-186
	timeoutSecond, err := strconv.ParseInt(gCtx.Request.Header.Get(mhttp.HTTPHeaderRequestTimeout), 10, 64)
	if err == nil {
		timeout = time.Duration(timeoutSecond) * time.Second
	}

// When strconv.ParseInt fails (e.g., with 'abc'), err != nil
// The code does NOT enter the if block, so invalid header is SILENTLY IGNORED
// Fallback: uses default timeout from paramtable.Get().HTTPCfg.RequestTimeoutMs
